import Foundation
import Testing
@testable import Rivalift

/// Runs the shared `scoring_vectors.json` (generated by scripts/scoring_reference.py) so the
/// app's estimates always match the server's scoring (section 9).
@Suite("Scoring vectors")
struct ScoringVectorTests {
    struct Vectors: Decodable {
        struct ConsistencyCase: Decodable {
            var name: String
            var input: LeagueScoreEstimator.WeekInput
            var expected: LeagueScoreEstimator.Breakdown
        }

        struct StrengthCase: Decodable {
            var name: String
            var comparison: StrengthScorer.Comparison
            var lifts: [StrengthScorer.LiftInput]
            var expected: StrengthScorer.Result
        }

        struct CustomCase: Decodable {
            struct Category: Decodable {
                var metric: CustomCategoryScorer.Metric
                var values: [String: Double?]
                var expected: [CustomCategoryScorer.Placement]
            }

            var name: String
            var categories: [Category]
            var expectedOverall: [CustomCategoryScorer.OverallEntry]
        }

        var consistency: [ConsistencyCase]
        var strength: [StrengthCase]
        var custom: [CustomCase]
    }

    static func load() throws -> Vectors {
        let bundle = Bundle(for: BundleToken.self)
        let url = try #require(bundle.url(forResource: "scoring_vectors", withExtension: "json"))
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        return try decoder.decode(Vectors.self, from: Data(contentsOf: url))
    }

    @Test func consistency() throws {
        let vectors = try Self.load()
        #expect(!vectors.consistency.isEmpty)
        for vector in vectors.consistency {
            let result = LeagueScoreEstimator.score(vector.input)
            #expect(result == vector.expected, "\(vector.name)")
            #expect(result.total <= LeagueConfig.default.maxScore)
        }
    }

    @Test func strength() throws {
        for vector in try Self.load().strength {
            let result = StrengthScorer.score(vector.lifts, comparison: vector.comparison)
            #expect(result.baselineLifts == vector.expected.baselineLifts, "\(vector.name)")
            switch (result.score, vector.expected.score) {
            case (nil, nil): break
            case let (actual?, expected?): #expect(abs(actual - expected) < 1e-4, "\(vector.name)")
            default: Issue.record("\(vector.name): expected \(String(describing: vector.expected.score)), got \(String(describing: result.score))")
            }
        }
    }

    @Test func custom() throws {
        for vector in try Self.load().custom {
            var placements: [[CustomCategoryScorer.Placement]] = []
            for category in vector.categories {
                let ranked = CustomCategoryScorer.rank(values: category.values, metric: category.metric)
                #expect(ranked == category.expected, "\(vector.name) – \(category.metric)")
                placements.append(ranked)
            }
            #expect(CustomCategoryScorer.overall(categoryPlacements: placements) == vector.expectedOverall, "\(vector.name)")
        }
    }

    @Test func categoryMetricsFromSets() {
        let sets = [
            SetSample(setType: .warmup, weightKg: 20, reps: 15),
            SetSample(weightKg: 14, reps: 10),
            SetSample(weightKg: 16, reps: 8),
            SetSample(weightKg: 18, reps: 6),
        ]
        #expect(CustomCategoryScorer.value(of: sets, metric: .maxReps, minReps: nil, previousBest: nil) == 10)
        #expect(CustomCategoryScorer.value(of: sets, metric: .totalReps, minReps: nil, previousBest: nil) == 24)
        #expect(CustomCategoryScorer.value(of: sets, metric: .heaviestWeight, minReps: 8, previousBest: nil) == 16)
        #expect(CustomCategoryScorer.value(of: sets, metric: .bestSetVolume, minReps: nil, previousBest: nil) == 140)
        // Spike rule: 50% for reps, 25% for weight.
        #expect(CustomCategoryScorer.value(of: sets, metric: .maxReps, minReps: nil, previousBest: 6) == 8)
        #expect(CustomCategoryScorer.value(of: sets, metric: .heaviestWeight, minReps: nil, previousBest: 14) == 16)
        #expect(CustomCategoryScorer.comparedValue(16, comparison: .improvement, previousBest: 14) == 2)
        #expect(CustomCategoryScorer.comparedValue(16, comparison: .improvement, previousBest: nil) == nil)
    }

    @Test func totalRepsCapped() {
        let spam = Array(repeating: SetSample(weightKg: 0, reps: 100), count: 30)
        #expect(CustomCategoryScorer.value(of: spam, metric: .totalReps, minReps: nil, previousBest: nil) == 2000)
    }
}
